select k,present,count(*),string_agg(n,',' order by n) from (select k,n,case k
 when 'function' then exists(select 1 from pg_proc p join pg_namespace s on s.oid=p.pronamespace where s.nspname='public' and p.proname=n)
 when 'table' then exists(select 1 from pg_class c join pg_namespace s on s.oid=c.relnamespace where s.nspname='public' and c.relname=n and c.relkind in ('r','p'))
 when 'view' then exists(select 1 from pg_class c join pg_namespace s on s.oid=c.relnamespace where s.nspname='public' and c.relname=n and c.relkind in ('v','m'))
 when 'column' then exists(select 1 from information_schema.columns where table_schema='public' and table_name=split_part(n,'.',1) and column_name=split_part(n,'.',2))
 when 'index' then exists(select 1 from pg_indexes where schemaname='public' and indexname=n)
 when 'constraint' then exists(select 1 from pg_constraint where conname=n)
end as present from o) t group by k,present order by k,present